    {
        var original = Content("Add all 200 g pasta.");
        CookingStepRelationshipProducer.ValidateFresh(original);
        Assert.Equal("Add all 200 g pasta.", CookingStepProjection.Read(original, 8).Sections[0].Steps[0].Text);
